// Generated by bloom from an `extern native` interface: regenerated on every build, never edited.
import { type ComponentType, createElement } from 'react';
import { type Child, Embed } from '@oxy.so/bloom-language';
import type { Spec } from './NativeBloomImage';

declare const require: (id: string) => unknown;

let native: Spec | undefined;

/** The TurboModule, loaded on first use (a web bundle or a Node test never loads it). */
function module(): Spec {
  if (!native) {
    const found = (require('./NativeBloomImage') as { default: Spec | null }).default;
    if (!found) throw new Error('Bloom: the native module BloomImage is not in this build (bloom build android links it)');
    native = found;
  }
  return native;
}

/** The native module is linked (always true in a `bloom build`; false on the web and in tests). */
export function isAvailable(): boolean {
  if (native) return true;
  try {
    return module() !== undefined;
  } catch {
    return false;
  }
}

export function prefetch(urls: readonly string[], memory: boolean): Promise<boolean> {
  return module().prefetch(urls as Array<string>, memory);
}

export function size(url: string): Promise<readonly number[]> {
  return module().size(url);
}

export function clear(memory: boolean, disk: boolean): Promise<boolean> {
  return module().clear(memory, disk);
}

type Host = ComponentType<Record<string, unknown>>;

/** A native view takes the space it is offered (a `.frame()` sizes it). */
const FILL = { flexGrow: 1, alignSelf: 'stretch' } as const;

/** The native component `name`, or `null` where the build does not link it (the web, tests). */
